values ('bbbb0004-0000-4000-8000-00000000000b', 'en', null, 'Introduction to Philosophy', 'A first tour of the big questions — how to argue well, what we can know, what is real, how to live, and how to live together. Structure adapted from OpenStax Introduction to Philosophy (CC BY 4.0).', null, 'foundations', 11, true, 'science', '{}')
