insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-00000000000b', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Philosophy is best described as the reasoned inquiry into…","options":["only the meaning of ancient texts","fundamental questions about knowledge, reality, and value","religious doctrine alone","unanswerable riddles with no method"],"answer":1,"explanation":"Philosophy uses argument to examine basic questions of knowledge, reality, and value — see ''What philosophy is''."},{"prompt":"A deductive argument is *valid* when…","options":["its premises are all true","if the premises were true, the conclusion would have to be true","most people accept the conclusion","it sounds persuasive"],"answer":1,"explanation":"Validity is about form: true premises would guarantee the conclusion — see ''Arguments''."},{"prompt":"Epistemology is the study of…","options":["beauty","what exists","knowledge and justified belief","right action"],"answer":2,"explanation":"Epistemology asks what knowledge is and when belief is justified."},{"prompt":"The ''mind-body problem'' asks…","options":["how to improve memory","how mental states relate to physical states","whether robots can feel","how the brain grows"],"answer":1,"explanation":"It concerns the relation between mind and body — see ''Metaphysics''."},{"prompt":"A consequentialist judges an action mainly by its…","options":["motive","conformity to duty","outcomes","cultural origin"],"answer":2,"explanation":"Consequentialism evaluates outcomes — see ''Ethics''."},{"prompt":"Kant''s deontology holds that morality rests on…","options":["maximizing pleasure","duties and universalizable rules","personal taste","obeying the powerful"],"answer":1,"explanation":"Duty and the categorical imperative anchor deontology."},{"prompt":"''You can''t trust his argument — look at his ugly job'' is an example of…","options":["a valid syllogism","the ad hominem fallacy","sound reasoning","an appeal to evidence"],"answer":1,"explanation":"Attacking the person rather than the claim is ad hominem — see ''Arguments''."},{"prompt":"A social contract theory of the state grounds political authority in…","options":["divine right","the agreement of the governed","military strength","inherited wealth"],"answer":1,"explanation":"Contract theories root legitimacy in consent — see ''Political philosophy''."}]}'::jsonb, null, 10),
  (2, 'What philosophy is — and how to argue', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what philosophy studies, break a passage into premises and a conclusion, and tell validity from soundness. Warm-up: from the diagnostic, why does ''valid'' *not* just mean ''true''?"},{"heading":"The idea","text":"Philosophy is the disciplined use of *argument* to examine basic questions — what we can know, what exists, and what is worth doing. An *argument* is a set of *premises* offered in support of a *conclusion*. A *deductive* argument is *valid* when its form guarantees that true premises would make the conclusion true; it is *sound* when it is valid *and* its premises are actually true. A *fallacy* is a common pattern of bad reasoning. *Ad hominem* attacks the arguer instead of the claim; a *straw man* attacks a distorted version of a view; *begging the question* assumes what it should prove."},{"heading":"Worked example","text":"Analyze: ''All humans are mortal. Socrates is human. So Socrates is mortal.'' Premises: (1) all humans mortal, (2) Socrates human. Conclusion: Socrates is mortal. The form makes it *valid*, and both premises are true, so it is also *sound*. Contrast: ''All birds can fly. A penguin is a bird. So a penguin can fly.'' This is *valid* in form but *unsound* — premise (1) is false."},{"heading":"Your turn","text":"Label each valid/invalid, then sound/unsound: (1) ''All cats are mammals; Felix is a cat; so Felix is a mammal.'' (2) ''If it rains the ground is wet; the ground is wet; so it rained.'' (3) ''All fish are green; a salmon is a fish; so a salmon is green.'' Answers: (1) valid and sound; (2) invalid — affirming the consequent, the wet ground could have another cause; (3) valid in form but unsound because the first premise is false."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking a valid argument must have a true conclusion — validity only says the conclusion follows *if* the premises hold. Mistake: calling any disagreement a fallacy. Exit: (a) What two things must a *sound* argument have? (b) Name the fallacy of attacking the person. Answers: valid form and all-true premises; ad hominem."}]}'::jsonb, 'Valid = good form. Sound = valid AND true premises. Keep these apart all course.', 13),
  (3, 'Epistemology: what can we know?', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"State the traditional analysis of knowledge and explain what skepticism challenges. Warm-up: can you *believe* something true by luck and still not *know* it?"},{"heading":"The idea","text":"The traditional analysis treats *knowledge* as *justified true belief*: to know that p, you must believe p, p must be true, and you must have good reason for believing it. *Skepticism* presses on the ''justified'' condition, asking whether our reasons ever rule out being deceived — Descartes imagined an ''evil demon'' feeding him false experiences. *Rationalists* (like Descartes) emphasize knowledge gained through reason; *empiricists* (like Hume and Locke) emphasize knowledge grounded in sense experience. Gettier cases show justified true belief can still fall short of knowledge when the justification is true only by luck."},{"heading":"Worked example","text":"Analyze a skeptical argument: ''If I cannot rule out that I am dreaming, I cannot know I am sitting here; I cannot rule out that I am dreaming; so I cannot know I am sitting here.'' The form is *valid*. To resist the conclusion you must reject a premise — for instance, denying that knowledge requires ruling out *every* far-fetched possibility. That is exactly where philosophers like Moore push back."},{"heading":"Your turn","text":"For each, is it knowledge on the justified-true-belief view? (1) You believe it is 3:00 because a stopped clock happens to read 3:00, and it is 3:00. (2) You believe water boils at 100°C at sea level, on good evidence, and it does. (3) You guess a coin landed heads, with no reason, and it did. Answers: (1) true and believed but the justification is defective — a classic Gettier-style failure; (2) yes, justified, true, and believed; (3) not knowledge — true belief without justification."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating a strong feeling of certainty as the same thing as justification. Mistake: thinking skepticism claims ''nothing is true'' — it questions our *justification*, not truth itself. Exit: (a) Name the three parts of the traditional analysis of knowledge. (b) What condition does the dreaming argument attack? Answers: justification, truth, belief; the justification condition."}]}'::jsonb, 'The classic recipe: knowledge = justified true belief (though Gettier complicated it).', 12),
  (4, 'Metaphysics: mind and free will', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"State the mind-body problem and lay out the main positions on free will. Warm-up: if every event has a prior cause, is any choice really ''up to you''?"},{"heading":"The idea","text":"*Metaphysics* studies what is real and how things fundamentally are. The *mind-body problem* asks how mental states (thoughts, feelings) relate to physical states (brains). *Dualism* (Descartes) holds mind and body are distinct kinds of thing; *physicalism* holds the mental is ultimately physical. On free will, *hard determinism* says every event is caused, so free will is an illusion; *libertarianism* (in the metaphysical sense) says some choices are genuinely undetermined; *compatibilism* (Hume) says freedom means acting from your own desires without external compulsion, which is consistent with determinism."},{"heading":"Worked example","text":"Analyze the incompatibilist argument: ''If determinism is true, my actions are fixed by causes before my birth; what is fixed before my birth is not up to me; so my actions are not up to me.'' It is *valid*. The compatibilist replies by rejecting the second premise — arguing that ''up to me'' means caused *by my own deliberation*, not uncaused. Notice both sides accept the same facts about causation; they disagree about the *meaning* of freedom."},{"heading":"Your turn","text":"Match each claim to dualism, physicalism, or compatibilism: (1) ''Pain just is a certain brain state.'' (2) ''The mind is a non-physical substance.'' (3) ''I act freely when I do what I want, even in a determined world.'' Then: (4) does compatibilism require rejecting determinism? Answers: (1) physicalism; (2) dualism; (3) compatibilism; (4) no — compatibilism accepts determinism and redefines freedom."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming determinism automatically destroys moral responsibility — compatibilists deny this. Mistake: confusing ''my choice was caused'' with ''my choice was coerced.'' Exit: (a) Which view says mind and body are different substances? (b) What does the compatibilist mean by ''free''? Answers: dualism; acting from one''s own desires without external compulsion."}]}'::jsonb, 'Determinism is a claim about causes; free will is about control. Compatibilism says both can hold.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"A sound argument is one that is…","options":["persuasive to most people","valid and has all true premises","valid but may have false premises","true even if invalid"],"answer":1,"explanation":"Soundness = validity plus true premises."},{"prompt":"''You should reject her theory because she is arrogant'' commits…","options":["begging the question","ad hominem","a valid deduction","appeal to evidence"],"answer":1,"explanation":"It attacks the person, not the claim."},{"prompt":"On the traditional analysis, knowledge is…","options":["any strong belief","justified true belief","whatever science proves","true belief alone"],"answer":1,"explanation":"Justification, truth, and belief together."},{"prompt":"Descartes'' ''evil demon'' is used to raise a problem about…","options":["ethics","the justification of our beliefs","political power","beauty"],"answer":1,"explanation":"It is a skeptical challenge to justification."},{"prompt":"Dualism claims that…","options":["the mind is just the brain","mind and body are distinct kinds of thing","free will is impossible","only matter exists"],"answer":1,"explanation":"Mind and body are different substances."},{"prompt":"Compatibilism holds that free will is…","options":["impossible if determinism is true","compatible with determinism","the same as randomness","an illusion"],"answer":1,"explanation":"Freedom as acting from one''s own desires, consistent with determinism."}]}'::jsonb, null, 8),
  (6, 'Ethics: three ways to judge an action', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Distinguish consequentialism, deontology, and virtue ethics, and apply each to a case. Warm-up: is a good action good because of its results, its rule, or the kind of person it reflects?"},{"heading":"The idea","text":"*Normative ethics* asks what makes actions right. *Consequentialism* — classically *utilitarianism* (Bentham, Mill) — judges an act by its outcomes, aiming at the greatest overall well-being. *Deontology* (Kant) judges by duties and rules: an act is right if its maxim could be willed as a universal law and treats persons as ends, never merely as means. *Virtue ethics* (Aristotle) shifts focus from acts to *character*, asking what a person of practical wisdom and virtue — courage, honesty, justice — would do, aiming at *eudaimonia*, or flourishing. Each captures a real moral intuition, and each faces hard cases."},{"heading":"Worked example","text":"Analyze a lie told to spare a friend''s feelings. A *consequentialist* weighs the harm of the lie against the comfort it gives and asks which produces more overall good. A *deontologist* asks whether ''lie when convenient'' could be a universal law — Kant argues it could not, so lying is wrong regardless of outcome. A *virtue ethicist* asks what an honest yet compassionate person would do, perhaps finding a truthful but kind way to speak. Same act, three different *reasons*."},{"heading":"Your turn","text":"Which theory does each slogan express? (1) ''The right act maximizes happiness for the most people.'' (2) ''Act only on a rule you could will for everyone.'' (3) ''Ask what a wise, courageous person would do.'' Then (4): name one objection to utilitarianism. Answers: (1) consequentialism/utilitarianism; (2) deontology; (3) virtue ethics; (4) it can seem to justify harming a few for the many — it may not adequately protect individual rights."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming these theories always disagree — they often recommend the same act for different reasons. Mistake: treating ''virtue ethics'' as merely ''be nice.'' Exit: (a) Which theory centers on duties and universal rules? (b) What does Aristotle call flourishing? Answers: deontology; eudaimonia."}]}'::jsonb, 'Consequences → consequentialism; duties → deontology; character → virtue ethics.', 13),
  (7, 'Political philosophy: justice and rights', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain social contract theory and contrast leading views of justice. Warm-up: what could make it legitimate for a state to make you obey its laws?"},{"heading":"The idea","text":"*Political philosophy* asks who may hold power and how a just society distributes benefits, burdens, and *rights*. *Social contract* theories (Hobbes, Locke, Rousseau) ground legitimate authority in the agreement of the governed. On *justice*, Rawls asks what principles we would choose behind a ''veil of ignorance,'' not knowing our own place in society, and argues we would protect basic liberties and allow inequalities only when they benefit the least advantaged. *Libertarians* like Nozick counter that justice is about respecting individual rights and voluntary exchange, so redistribution can wrong the people taxed. *Rights* may be *negative* (freedom from interference) or *positive* (entitlements to certain goods)."},{"heading":"Worked example","text":"Analyze a dispute over taxation for public healthcare. A *Rawlsian* argues that behind the veil of ignorance, not knowing if you''d be sick or poor, you would endorse arrangements that help the least advantaged — supporting the program. A *Nozickian* replies that taxing one person to fund another''s care violates their right to their own holdings unless they consent. The clash is not over facts but over what *justice* fundamentally protects: fair distribution or individual entitlement."},{"heading":"Your turn","text":"Classify each: (1) ''The state is legitimate because citizens consent to it.'' (2) ''Choose principles as if you didn''t know your place in society.'' (3) ''A right to free speech is a right against interference.'' (4) ''A right to education is a claim to be provided something.'' Answers: (1) social contract theory; (2) Rawls'' veil of ignorance; (3) a negative right; (4) a positive right."},{"heading":"Common mistakes & exit ticket","text":"Mistake: confusing *legitimacy* (who may rule) with *justice* (how goods and rights should be arranged). Mistake: assuming everyone means the same thing by ''rights.'' Exit: (a) Whose thought experiment is the veil of ignorance? (b) A right to *non-interference* is called what kind of right? Answers: Rawls; a negative right."}]}'::jsonb, 'Legitimacy asks who *may* rule; justice asks how goods and rights *should* be distributed.', 12),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"valid","translation":"a deductive argument whose form guarantees the conclusion if the premises are true","example":"The argument is valid, but is it sound?"},{"term":"sound","translation":"a valid argument that also has all true premises","example":"A sound argument gives you a true conclusion."},{"term":"epistemology","translation":"the branch of philosophy studying knowledge and justified belief","example":"Skepticism is a central topic in epistemology."},{"term":"deontology","translation":"the ethical view that right action is defined by duties and universal rules","example":"Kant''s deontology forbids lying even to help."},{"term":"utilitarianism","translation":"the consequentialist view that the right act maximizes overall well-being","example":"Utilitarianism weighs everyone''s happiness equally."},{"term":"social contract","translation":"the idea that political authority is legitimated by the agreement of the governed","example":"Locke used a social contract to justify limited government."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"Utilitarianism evaluates actions by…","options":["their motives","conformity to duty","their overall consequences for well-being","the agent''s character"],"answer":2,"explanation":"Consequences and overall well-being."},{"prompt":"Kant''s test asks whether the rule behind your act…","options":["feels right","could be willed as a universal law","maximizes pleasure","is legal"],"answer":1,"explanation":"The categorical imperative and universalizability."},{"prompt":"Aristotle''s virtue ethics centers on…","options":["outcomes","duties","character and flourishing","social contracts"],"answer":2,"explanation":"Virtue, practical wisdom, and eudaimonia."},{"prompt":"Rawls'' veil of ignorance is a device for choosing principles of…","options":["knowledge","justice","logic","mind"],"answer":1,"explanation":"Fair principles chosen without knowing your place."},{"prompt":"A right to non-interference (like free speech) is a…","options":["positive right","negative right","legal duty","social contract"],"answer":1,"explanation":"Negative rights are freedoms from interference."},{"prompt":"A common objection to utilitarianism is that it may…","options":["ignore consequences","fail to protect individuals for the sake of the majority","require universalizable rules","reject all pleasure"],"answer":1,"explanation":"It can seem to sacrifice the few for the many."}]}'::jsonb, null, 8),
  (10, 'Applied project: construct and defend an argument', 'writing', '{"sections":[{"heading":"The task","text":"Choose one contestable philosophical claim (for example: ''We can never be certain the external world exists,'' ''Lying is always wrong,'' or ''A just society must reduce inequality''). Construct a clear argument for your position and defend it against the strongest objection you can find — this is a reasoning exercise, not a matter of picking the ''approved'' answer."},{"heading":"Milestones","text":"1) State your thesis in one sentence. 2) Give an argument with numbered premises and a conclusion, and say whether it is meant to be deductive (aiming at validity) or inductive (aiming at strong support). 3) Present the single best objection to your view, stated fairly and not as a straw man. 4) Reply to that objection, showing which premise it targets and why your view survives — or honestly note where it is weakened."},{"heading":"Self-check rubric","text":"✔ The thesis is specific and contestable. ✔ The argument is laid out as explicit premises and a conclusion. ✔ You correctly labeled it valid/sound or strong/weak. ✔ The objection is charitable and genuinely challenging. ✔ Your reply engages the objection instead of dodging it. If all five hold, you have argued like a philosopher — clarity and fairness matter more than winning."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-00000000000b' and l.position = v.pos
);
